def is_palindrome(s: str) -> bool:
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def find_two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen:
            return [seen[diff], i]
        seen[num] = i
    return []

def calculate_two_sum_indices(numbers_list, target_sum_value):
    # Dictionary to store seen numbers
    lookup_dictionary = {}
    # Iterate through numbers
    for current_index, current_number in enumerate(numbers_list):
        complement_value = target_sum_value - current_number
        if complement_value in lookup_dictionary:
            result_indices_pair = [lookup_dictionary[complement_value], current_index]
            return result_indices_pair
        lookup_dictionary[current_number] = current_index
    empty_fallback_list = []
    return empty_fallback_list

def flatten_two_dimensional_array(two_dimensional_array_input):
    """Flattens a 2D list into a 1D list."""
    flattened_result_list = []
    # Loop over the outer list
    for single_row_list in two_dimensional_array_input:
        # Loop over items in inner list
        for inner_element_item in single_row_list:
            flattened_result_list = flattened_result_list + [inner_element_item]
    return flattened_result_list

